  "ice sheet": { c: "n", u: "冰蓋、大冰原(覆蓋陸地的大片冰層);the Greenland ice sheet。", e: "Scientists are studying how fast the ice sheet is melting.", z: "科學家正在研究冰蓋融化的速度。" },
  "in case of": { c: "p", u: "in case of + 名詞 = 萬一發生…時(常見於告示:In case of fire, …);in case + 子句 = 以防萬一。", e: "In case of emergency, press the red button.", z: "如遇緊急狀況,請按紅色按鈕。" },
  "in the air": { c: "p", u: "瀰漫在空氣中、到處都感受得到;也有「在空中」之意。", e: "Christmas is in the air.", z: "到處都洋溢著聖誕氣氛。" },
  "less expensive": { c: "p", u: "較便宜(比較級);less + 形容詞 + than = 比較不…;the least expensive = 最便宜。", e: "The train is less expensive than the high-speed rail.", z: "火車比高鐵便宜。" },
  "log into": { c: "v", u: "log into / log in to + 帳號、網站 = 登入;登出是 log out (of)。", e: "Log into the hotel Wi-Fi with your room number.", z: "用房號登入飯店無線網路。" },
  "long distance call": { c: "n", u: "長途電話(也寫 long-distance call);make a long distance call。", e: "Long distance calls from the room will be charged.", z: "從房間打長途電話要收費。" },
  "Lost and Found": { c: "n", u: "失物招領處(= lost and found office);go to the Lost and Found。", e: "Check the Lost and Found if you left something on the bus.", z: "東西掉在公車上,可以去失物招領處問。" },
  "main course": { c: "n", u: "主菜(= main dish);前菜 appetizer / starter、甜點 dessert。", e: "For the main course, I'll have the steak.", z: "主菜我要牛排。" },
  "make a call": { c: "v", u: "打電話 = make a phone call / call sb;make a call to + 人;collect call 對方付費。", e: "Excuse me, where can I make a call?", z: "請問哪裡可以打電話?" },
  "mass tourism": { c: "n", u: "大眾觀光(大批遊客湧入);相對 sustainable tourism(永續觀光)。", e: "Mass tourism can damage fragile ecosystems.", z: "大眾觀光可能破壞脆弱的生態系。" },
  "National Palace Museum": { c: "pn", u: "國立故宮博物院(前面加 the);翠玉白菜是 the Jadeite Cabbage。", e: "The National Palace Museum has a huge collection of Chinese art.", z: "故宮收藏大量中華藝術品。" },
  "news report": { c: "n", u: "新聞報導;according to the news report(根據新聞報導)。", e: "According to a news report, the road is closed.", z: "根據新聞報導,那條路封閉了。" },
  "night market": { c: "n", u: "夜市;go to a night market、at the night market。", e: "Shilin is one of the largest night markets in Taipei.", z: "士林是臺北最大的夜市之一。" },
  "on foot": { c: "p", u: "步行(on foot 不加冠詞,= walk);對照 by bus、by car。", e: "The museum is only ten minutes from here on foot.", z: "博物館走路只要十分鐘。" },
  "on sale": { c: "p", u: "特價中(美式);也可指「上市販售中」;for sale = 待售、出售中。", e: "These jackets are on sale at 30% off.", z: "這些外套打七折特價中。" },
  "overhead bin": { c: "n", u: "上方置物櫃(= overhead compartment);stow your bag in the overhead bin。", e: "There's no more space in the overhead bin.", z: "上方置物櫃已經沒空間了。" },
  "oyster omelet": { c: "n", u: "蚵仔煎;oyster = 牡蠣、蚵仔。", e: "You must try the oyster omelet at this night market.", z: "這個夜市的蚵仔煎一定要吃。" },
  "prior to": { c: "p", u: "prior to + 名詞 / V-ing = 在…之前(正式,= before);to 是介系詞。", e: "Please arrive at the gate 30 minutes prior to departure.", z: "請在起飛前 30 分鐘抵達登機門。" },
  "put off": { c: "v", u: "put off = 延後(= postpone,put off + V-ing);put sb off = 使人反感、倒胃口。", e: "The strong smell of stinky tofu puts some tourists off.", z: "臭豆腐的濃烈氣味讓一些遊客卻步。" },
  "put through": { c: "v", u: "put sb through (to + 人) = (電話)幫某人接通、轉接。", e: "Could you put me through to Room 512?", z: "可以幫我轉接 512 號房嗎?" },
  "regard as": { c: "v", u: "regard A as B = 把 A 視為 B(= consider A (to be) B、think of A as B);被動 A is regarded as B。", e: "Taroko is regarded as one of the most beautiful places in Taiwan.", z: "太魯閣被視為臺灣最美的地方之一。" },
  "rock formation": { c: "n", u: "岩石地形、奇岩(可數)。", e: "Yehliu Geopark is famous for its unusual rock formations.", z: "野柳地質公園以奇特的岩石地形聞名。" },
  "rule of thumb": { c: "p", u: "經驗法則、粗略的原則;as a rule of thumb(根據經驗)。", e: "As a rule of thumb, tip 15 to 20 percent in American restaurants.", z: "依經驗,在美國餐廳大約給 15% 到 20% 的小費。" },
  "security check": { c: "n", u: "安全檢查;go through the security check(通過安檢)。", e: "Remove your laptop from your bag at the security check.", z: "安檢時請把筆電從包包拿出來。" },
  "selfie stick": { c: "n", u: "自拍棒;有些景點、博物館禁止使用(be banned)。", e: "Selfie sticks are not allowed in this museum.", z: "這間博物館禁止使用自拍棒。" },
  "service charge": { c: "n", u: "服務費;a 10% service charge is added to the bill(帳單加收一成服務費)。", e: "A 10% service charge will be added to your bill.", z: "帳單會另加一成服務費。" },
  "shaved ice": { c: "n", u: "剉冰;mango shaved ice(芒果冰)。", e: "Mango shaved ice is perfect on a hot summer day.", z: "炎熱夏天吃芒果冰最棒了。" },
