  "ski resort": { c: "n", u: "滑雪度假區;go skiing(去滑雪)。", e: "Hokkaido has many world-class ski resorts.", z: "北海道有很多世界級滑雪場。" },
  "spare time": { c: "n", u: "空閒時間(不可數,= free time);in one's spare time(在空閒時)。", e: "What do you like to do in your spare time?", z: "你空閒時喜歡做什麼?" },
  "stand for": { c: "v", u: "stand for = 代表、是…的縮寫(MRT stands for Mass Rapid Transit);否定句也有「容忍」之意。", e: "What does VAT stand for?", z: "VAT 是什麼的縮寫?" },
  "stinky tofu": { c: "n", u: "臭豆腐;smells strong but tastes great(聞起來臭、吃起來香)。", e: "Stinky tofu smells strong but tastes great.", z: "臭豆腐聞起來很臭,吃起來很香。" },
  "suffer from": { c: "v", u: "suffer from + 病痛 / 問題 = 患有、受…之苦(suffer from jet lag 時差不適)。", e: "Many travelers suffer from jet lag after long flights.", z: "很多旅客長途飛行後會有時差不適。" },
  "sustainable tourism": { c: "n", u: "永續觀光(兼顧環境、文化與在地經濟);eco-tourism = 生態旅遊。", e: "Sustainable tourism protects both nature and local culture.", z: "永續觀光同時保護自然與在地文化。" },
