  "take pictures": { c: "v", u: "拍照 = take photos;take a picture of + 人 / 物;No photos 禁止拍照。", e: "Are we allowed to take pictures inside the temple?", z: "廟裡可以拍照嗎?" },
  "tap water": { c: "n", u: "自來水(不可數)。", e: "Is it safe to drink the tap water here?", z: "這裡的自來水可以直接喝嗎?" },
