  "tour guide": { c: "n", u: "導遊;tour leader / tour escort = 領隊;a licensed tour guide(有執照的導遊)。", e: "Our tour guide speaks four languages.", z: "我們的導遊會說四種語言。" },
  "travel agency": { c: "n", u: "旅行社(公司);book a tour through a travel agency(透過旅行社報名)。", e: "We booked the trip through a local travel agency.", z: "我們透過當地旅行社訂了這趟行程。" },
  "travel agent": { c: "n", u: "旅行社業務人員(人);travel agency 是公司。", e: "Our travel agent arranged all the hotels for us.", z: "旅行社的業務幫我們安排了所有飯店。" },
  "traveler's check": { c: "n", u: "旅行支票(現已少用);cash a traveler's check(兌現旅行支票)。", e: "Can I cash a traveler's check here?", z: "這裡可以兌現旅行支票嗎?" },
  "twin room": { c: "n", u: "雙床房(兩張單人床);double room = 一張雙人床。", e: "We'd like a twin room with two single beds.", z: "我們想要有兩張單人床的雙床房。" },
  "upset stomach": { c: "n", u: "腸胃不適;have an upset stomach。", e: "I have an upset stomach. Is there a pharmacy nearby?", z: "我胃不舒服,附近有藥局嗎?" },
  "US dollar": { c: "n", u: "美元;exchange NT dollars into US dollars(臺幣換美元)。", e: "How many US dollars would you like to exchange?", z: "您想換多少美元?" },
  "vacation destination": { c: "n", u: "度假地點;a popular vacation destination(熱門度假地)。", e: "Bali is a popular vacation destination.", z: "峇里島是熱門的度假地點。" },
  "World Heritage Site": { c: "pn", u: "世界遺產(聯合國教科文組織登錄);be listed as a World Heritage Site。", e: "The old town was listed as a World Heritage Site.", z: "這座古城被列為世界遺產。" }
