  "sort through": { c: "v", u: "sort through + 東西 = 分類整理、仔細翻找。", e: "I sorted through my photos after the trip.", z: "旅行回來後我整理了照片。" },
  "specialize in": { c: "v", u: "specialize in + 名詞 / V-ing = 專營、專攻。", e: "This shop specializes in handmade soap.", z: "這家店專賣手工皂。" },
  "split the bill": { c: "v", u: "平分帳單(= go Dutch);split the bill three ways = 三人平分。", e: "Shall we split the bill?", z: "我們要平分帳單嗎?" },
  "start off": { c: "v", u: "出發、開始;start off with + 名詞 = 以…開始。", e: "We started off the day with a big breakfast.", z: "我們以豐盛的早餐展開這一天。" },
  "stay alert": { c: "v", u: "保持警覺(stay + 形容詞 = 保持某狀態)。", e: "Stay alert for pickpockets on crowded trains.", z: "在擁擠的列車上要提防扒手。" },
  "stay in": { c: "v", u: "stay in + 地方 = 住在(stay in a hotel);單獨 stay in = 待在家、不出門。", e: "We stayed in a small guesthouse by the sea.", z: "我們住在海邊一間小民宿。" },
  "stay warm": { c: "v", u: "保暖(stay + 形容詞 = 保持某狀態)。", e: "Bring a jacket to stay warm on the mountain.", z: "帶件外套,在山上才能保暖。" },
  "stop by": { c: "v", u: "stop by + 地方 = 順道拜訪、順路去。", e: "Let's stop by the bakery on the way back.", z: "回去路上順道去一下麵包店吧。" },
  "stop in": { c: "v", u: "stop in (at + 地方) = 順道進去、短暫停留。", e: "We stopped in at a café for a quick coffee.", z: "我們順道進咖啡館喝杯咖啡。" },
  "stop over": { c: "v", u: "(長途旅行中)中途停留(stop over in + 城市);名詞 stopover。", e: "We stopped over in Singapore for two nights.", z: "我們在新加坡中途停留兩晚。" },
  "take a right": { c: "v", u: "右轉(= turn right);take a left = 左轉。", e: "Take a right at the next corner.", z: "在下個轉角右轉。" },
  "take advantage of": { c: "v", u: "take advantage of + 名詞 = 善用、利用(機會);也有「佔…便宜」之意。", e: "Take advantage of the free shuttle bus.", z: "好好利用免費接駁車。" },
  "take lives": { c: "v", u: "奪走性命(災害、疾病造成死亡)。", e: "The earthquake took many lives.", z: "那場地震奪走了許多性命。" },
  "take on": { c: "v", u: "take on + 工作 / 責任 = 承擔、接下;也表示「呈現(某種外觀)」。", e: "She took on the role of tour leader.", z: "她接下了領隊的工作。" },
  "take one's breath away": { c: "v", u: "令人屏息、美得說不出話(形容詞 breathtaking)。", e: "The sea of clouds took my breath away.", z: "雲海美得讓我屏息。" },
  "take out": { c: "v", u: "拿出、取出(take out your passport);也表示「外帶」(takeout food)。", e: "Please take out your laptop for the security check.", z: "安檢時請把筆電拿出來。" },
  "take pleasure in": { c: "v", u: "take pleasure in + V-ing = 樂於、喜歡做…。", e: "The owner takes pleasure in sharing local stories.", z: "老闆很樂於分享在地故事。" },
  "take the plunge": { c: "v", u: "放手一試、下定決心做(有點冒險的事)。", e: "I finally took the plunge and tried bungee jumping.", z: "我終於鼓起勇氣去玩高空彈跳。" },
  "tell off": { c: "v", u: "tell sb off = 責罵某人。", e: "The guard told off a tourist for touching the statue.", z: "警衛責罵了一名觸摸雕像的遊客。" },
  "travel light": { c: "v", u: "輕裝旅行、少帶行李(= pack light)。", e: "I always travel light with just a backpack.", z: "我總是只背一個背包輕裝旅行。" },
  "try on": { c: "v", u: "試穿(try on + 衣服 / try it on,代名詞放中間)。", e: "Can I try on this jacket?", z: "我可以試穿這件外套嗎?" },
  "turn down": { c: "v", u: "turn down + 音量 = 調小(turn it down);turn down + 邀請 = 拒絕。", e: "Could you turn down the music, please?", z: "可以把音樂關小聲一點嗎?" },
  "turn left": { c: "v", u: "左轉(= take a left);turn right = 右轉。", e: "Turn left at the traffic light.", z: "在紅綠燈左轉。" },
  "turn out": { c: "v", u: "turn out = 出席、到場(Thousands turned out for the parade);也表示「結果是」。", e: "Thousands of people turned out for the parade.", z: "成千上萬的人前來看遊行。" },
  "turn out to be": { c: "v", u: "turn out to be + 名詞 / 形容詞 = 結果是、原來是。", e: "The small café turned out to be the best part of our trip.", z: "那家小咖啡館結果成了旅程中最棒的部分。" },
  "turn right": { c: "v", u: "右轉(= take a right);turn left = 左轉。", e: "Turn right after the bridge.", z: "過橋後右轉。" },
