  "wait in line": { c: "v", u: "排隊等候(= queue / line up)。", e: "We waited in line for an hour for the ride.", z: "我們排了一個小時隊等玩這個設施。" },
  "wait one's turn": { c: "v", u: "等輪到自己(不插隊)。", e: "Please wait your turn at the counter.", z: "請在櫃台前依序等候。" },
  "walk through": { c: "v", u: "walk through + 地方 = 走過、穿過;walk sb through + 程序 = 一步步帶某人做。", e: "The guide walked us through the check-in process.", z: "導遊一步步帶我們辦理報到手續。" },
  "wash the dishes": { c: "v", u: "洗碗(= do the dishes)。", e: "Guests are asked to wash the dishes after cooking.", z: "房客煮完飯後要自己洗碗。" },
  "hollow out": { c: "v", u: "hollow out + 名詞 = 挖空(被動 be hollowed out;hollowed-out = 挖空的)。", e: "The canoe was made from a hollowed-out tree.", z: "這艘獨木舟是用挖空的樹幹做的。" },
  "lean to the right": { c: "v", u: "往右靠、向右傾斜(lean to + 方向);lean against = 靠著。", e: "Please lean to the right to let others pass.", z: "請靠右讓其他人通過。" },
  "learn from": { c: "v", u: "learn from + 人 / 經驗 = 從…學習。", e: "We learned a lot from the local farmers.", z: "我們從當地農民身上學到很多。" },
  "manage to": { c: "v", u: "manage to + V = 設法做到、成功做到(強調克服困難)。", e: "We managed to catch the last train.", z: "我們設法趕上了末班車。" },
  "push aside": { c: "v", u: "push aside + 名詞 = 推到一邊、擱置不理。", e: "He pushed aside the branches to see the waterfall.", z: "他撥開樹枝去看瀑布。" },
  "range from ... to ...": { c: "v", u: "range from A to B = 範圍從 A 到 B(價格、年齡、溫度)。", e: "Room rates range from 2,000 to 5,000 dollars.", z: "房價從 2,000 元到 5,000 元不等。" },
  "rank ... highly": { c: "v", u: "rank sth highly = 給予高評價;be ranked highly = 排名很高。", e: "Travelers rank this hotel highly for its service.", z: "旅客高度評價這家飯店的服務。" },
  "rave about": { c: "v", u: "rave about + 名詞 = 極力稱讚、讚不絕口;rave review = 好評。", e: "Everyone raves about the beef noodles here.", z: "大家都對這裡的牛肉麵讚不絕口。" },
  "refuse entry": { c: "v", u: "拒絕入境(refuse sb entry / be refused entry)。", e: "Travelers without a valid visa may be refused entry.", z: "沒有有效簽證的旅客可能被拒絕入境。" },
  "remain seated": { c: "v", u: "保持坐著(機上廣播固定說法);remain + 過去分詞 / 形容詞 = 保持某狀態。", e: "Please remain seated until the plane stops completely.", z: "飛機完全停止前請留在座位上。" },
  "replace ... with": { c: "v", u: "replace A with B = 用 B 取代 A(A 被換掉)。", e: "Many cafés have replaced plastic straws with paper ones.", z: "很多咖啡館已經把塑膠吸管換成紙吸管。" },
  "return the car": { c: "v", u: "還車(租車);pick up the car = 取車。", e: "Please return the car with a full tank.", z: "還車時請加滿油。" },
  "rocket to fame": { c: "v", u: "一舉成名(rocket 當動詞 = 急速上升);make sb rocket to fame。", e: "The small bakery rocketed to fame after a TV show.", z: "這家小麵包店上了電視節目後一舉成名。" },
  "shift gears": { c: "v", u: "改變方向、轉換策略(原意是換檔)。", e: "After the rain started, we shifted gears and visited a museum.", z: "開始下雨後我們改變計畫,去參觀博物館。" },
  "shore up": { c: "v", u: "shore up + 名詞 = 支撐、強化(shore up the economy)。", e: "The city is trying to shore up its tourism industry.", z: "這座城市正設法強化觀光產業。" },
  "speed up": { c: "v", u: "加速、加快(speed up + 流程);反義 slow down。", e: "The new e-gates speed up immigration checks.", z: "新的自動通關閘門加快了入境查驗。" },
  "spin the globe": { c: "v", u: "轉動地球儀(比喻隨機挑一個旅行目的地)。", e: "Just spin the globe and pick your next destination!", z: "轉一下地球儀,挑選你的下個目的地吧!" },
  "squeeze in": { c: "v", u: "squeeze in + 人 / 事 = 擠出時間或位子安排(squeeze us in 幫我們擠出位子)。", e: "The restaurant squeezed us in without a reservation.", z: "沒有訂位,餐廳還是幫我們擠出了位子。" },
  "ward off": { c: "v", u: "ward off + 名詞 = 避開、驅趕(邪靈、疾病、蚊蟲)。", e: "Firecrackers are said to ward off evil spirits.", z: "據說鞭炮可以驅邪。" },
  "waste your breath": { c: "v", u: "白費唇舌(Don't waste your breath = 別白費口舌了)。", e: "Don't waste your breath arguing with him.", z: "別白費口舌跟他爭了。" },
  "propose / marry": { c: "v", u: "propose (to sb) = 求婚;marry sb = 和某人結婚(不加 with);get married (to sb) = 結婚。", e: "He proposed to her on a boat in Sun Moon Lake.", z: "他在日月潭的船上向她求婚。" }
